// LC 543。返回值是以节点数计的子树高度（叶子为 1、空树为 0）；best 记下以本节点为拐点的路径。
// 换 LC 104：删掉 best，直接 return Math.max(left, right) + 1，空树返回 0。
// 换 LC 110：高度差大于 1 时返回 -1，父节点见到 -1 立刻继续上传。
// 换 LC 124：拒绝空树，best 每次初始化为 Long.MIN_VALUE；贡献与累计用 long。左右贡献先与 0 取最大，用 node.val + left + right 更新 best，返回 node.val + max(left, right)，最终检查 int 范围。
static int diameterOfBinaryTree(TreeNode root) {
    int[] best = new int[1];
    chainEdges(root, best);
    return best[0];
}

static int chainEdges(TreeNode node, int[] best) {
    if (node == null) return 0;
    int left = chainEdges(node.left, best);
    int right = chainEdges(node.right, best);
    best[0] = Math.max(best[0], left + right); // 拐弯路径只写全局，不返回给父节点
    return Math.max(left, right) + 1;          // 父节点只能再接左右中较长的一条
}

// LC 94。指针负责一路向左，栈保存还没访问的祖先；弹出时左子树已经空了，才记录根。
// 改前序：先压根，弹出时立刻记录，然后先压右再压左。
// 改后序：按根-右-左做上面的前序，最后 Collections.reverse(ans)。
// 改 LC 230：ans 不必整表保存，弹出计数到 k 就 return cur.val。
static List<Integer> inorderTraversal(TreeNode root) {
    List<Integer> ans = new ArrayList<>();
    ArrayDeque<TreeNode> stack = new ArrayDeque<>();
    TreeNode cur = root;
    while (cur != null || !stack.isEmpty()) {
        while (cur != null) {
            stack.push(cur);
            cur = cur.left;
        }
        cur = stack.pop();
        ans.add(cur.val);
        cur = cur.right;
    }
    return ans;
}

// LC 102。每轮开始时 queue.size() 就是本层节点数，循环里只处理这么多个，下一层自然留在队列尾部。
// 换 LC 199：本层循环里最后一个 cur.val 才 add 进答案，每层一个数。
// 换 LC 103：按层号决定 level 头插还是尾插，队列仍从左到右扩展。
static List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> ans = new ArrayList<>();
    if (root == null) return ans;
    ArrayDeque<TreeNode> queue = new ArrayDeque<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        int size = queue.size();
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode cur = queue.poll();
            level.add(cur.val);
            if (cur.left != null) queue.offer(cur.left);
            if (cur.right != null) queue.offer(cur.right);
        }
        ans.add(level);
    }
    return ans;
}

// LC 98。传开区间 (low, high)，左子树把上界收成当前值，右子树把下界收成当前值。
// 用 long 是因为节点值可以取到 int 的两端，初始边界要落在 int 外面。
// 本题不允许相等。若新题只允许某一侧放重复值，须为上下界分别携带开闭标志并向下传递，不能把所有比较统一放宽。
// 换 LC 230 不必用区间：走中序，第 k 次弹出即为答案。
static boolean isValidBST(TreeNode root) {
    return inRange(root, Long.MIN_VALUE, Long.MAX_VALUE);
}

static boolean inRange(TreeNode node, long low, long high) {
    if (node == null) return true;
    if (node.val <= low || node.val >= high) return false;
    return inRange(node.left, low, node.val) && inRange(node.right, node.val, high);
}

